import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        t_str = next(iterator)
        t = int(t_str)
    except StopIteration:
        return

    results = []

    for _ in range(t):
        try:
            n = int(next(iterator))
            m = int(next(iterator))
        except StopIteration:
            break

        adj = [[] for _ in range(n + 1)]

        for _ in range(m):
            u = int(next(iterator))
            v = int(next(iterator))
            adj[u].append(v)

        visited = [False] * (n + 1)
        queue = deque([1])
        visited[1] = True
        jury = []

        while queue:
            u = queue.popleft()
            jury.append(u)
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    queue.append(v)

        contestants = [i for i in range(1, n + 1) if not visited[i]]

        if not jury or not contestants:
            results.append("No")
        else:
            results.append("Yes")
            results.append(f"{len(jury)} {len(contestants)}")
            results.append(" ".join(map(str, jury)))
            results.append(" ".join(map(str, contestants)))

    print("\n".join(results))

if __name__ == "__main__":
    solve()
